<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Accessor\SnippetVersionSnippetAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetVersionSnippetAccessor trait.
 *
 * Covers null default, string/VO assignment via withSnippet,
 * getSnippet/snippet accessors, and isSnippetChanged with/without original.
 */
class SnippetVersionSnippetAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSnippet creates a new instance with the Snippet set
     * from a string value, and getSnippet returns the primitive string.
     */
    public function testWithSnippetFromString(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionSnippetAccessorUnitTest();

        // Act
        $result = $holder->withSnippet(new SnippetRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new SnippetRef('one'), $result->getSnippet());
    }
    /**
     * Asserts that withsnippet has access to the value object
     * from a string value, and getSnippet returns the primitive string.
     */
    public function testWithSnippetFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionSnippetAccessorUnitTest();

        // Act
        $result = $holder->withSnippet(new SnippetRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new SnippetRef('one'), $result->snippet()->value());
    }
    public function testChangedSnippet(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionSnippetAccessorUnitTest()->withSnippet(new SnippetRef('one'));
        $original = $holder->withSnippet(new SnippetRef('one'));
        $same = $holder->withSnippet(new SnippetRef('one'));
        $modified = $holder->withSnippet(new SnippetRef('other'));

        // Act
        $withSame = $original->isSnippetChanged($same);
        $withDiferent = $original->isSnippetChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSnippetVersionSnippetAccessorUnitTest
{
    use SnippetVersionSnippetAccessor;
}
